 "content": "from collections import deque


def transform(grid):
    """Color dense 3x3 cores within each 4-connected nonzero shape."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    labels = [[-1] * w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or labels[r][c] != -1:
                continue
            label = len(components)
            q = deque([(r, c)])
            labels[r][c] = label
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0
                            and labels[nr][nc] == -1):
                        labels[nr][nc] = label
                        q.append((nr, nc))
            markers = [(rr, cc, grid[rr][cc]) for rr, cc in cells if grid[rr][cc] > 1]
            components.append(markers)

    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 1:
                continue
            if all(grid[rr][cc] != 0
                   for rr in range(r - 1, r + 2)
                   for cc in range(c - 1, c + 2)):
                markers = components[labels[r][c]]
                if markers:
                    _, _, color = min(markers,
                                      key=lambda m: (abs(r - m[0]) + abs(c - m[1]), m[0], m[1]))
                    out[r][c] = color
    return out
