 "content": "def transform(grid):
    """Paint 1-valued cells that lie in the rectangular frame of a seed component."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0 and not seen[nr][nc]:
                        seen[nr][nc] = True
                        stack.append((nr, nc))
            seeds = [(rr, cc, grid[rr][cc]) for rr, cc in cells if grid[rr][cc] not in (0, 1)]
            if seeds:
                components.append((min(rr for rr, cc in cells), min(cc for rr, cc in cells),
                                   max(rr for rr, cc in cells), max(cc for rr, cc in cells), seeds))

    for top, left, bottom, right, seeds in components:
        color = seeds[0][2]
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                if grid[r][c] == 1 and (r == top or r == bottom or c == left or c == right):
                    out[r][c] = color
    return out
