def transform(grid):
    """Expand each sparse colored seed into matching local cells of its shape."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 1):
                continue
            queue = deque([(r, c)])
            seen = {(r, c)}
            while queue:
                rr, cc = queue.popleft()
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen
                            and grid[nr][nc] in (1, color)):
                        seen.add((nr, nc))
                        queue.append((nr, nc))
            cells = list(seen)
            top, bottom = min(y for y, x in cells), max(y for y, x in cells)
            left, right = min(x for y, x in cells), max(x for y, x in cells)
            # Color only interior ones in the seed's connected object; the demo shows
            # solid 3x3 patches within larger connected masses are selected.
            for rr, cc in cells:
                if grid[rr][cc] == 1 and 0 < rr < h - 1 and 0 < cc < w - 1:
                    if all(grid[y][x] == 1
                           for y in range(rr - 1, rr + 2)
                           for x in range(cc - 1, cc + 2)):
                        out[rr][cc] = color
    return out
