for k,p in [(1,"/tmp/task300497_pair1.json"),(2,"/tmp/task300497_pair2.json"),(3,"/tmp/task300497_pair3.json")]:
 si,so=json.load(open(p));g=[list(map(int,r.split())) for r in si.splitlines() if r.strip()];o=[list(map(int,r.split())) for r in so.splitlines() if r.strip()];h=len(g);w=min(map(len,g));
 for row in g:row.extend([0]*(w-len(row)))
 for row in o:row.extend([0]*(w-len(row)))
 print("CASE",k)
 for r in range(h):
  for c in range(w):
   if g[r][c]>1:
    coords=[(y-r,x-c) for y in range(h) for x in range(w) if g[y][x]==1 and o[y][x]==g[r][c]]
    print("seed",r,c,"clusters",end=" ")
    seen=set(); cl=[]
    for pt in coords:
     if pt in seen:continue
     q=[pt];seen.add(pt);co=[]
     while q:
      y,x=q.pop();co.append((y,x))
      for z in [(y-1,x),(y+1,x),(y,x-1),(y,x+1)]:
       if z in coords and z not in seen:seen.add(z);q.append(z)
     cl.append((len(co),(min(y for y,x in co),max(y for y,x in co),min(x for y,x in co),max(x for y,x in co))))
    print(cl)'''
r=terminal('python3 -c '+shlex.quote(script),timeout=180)
print(r['output']); print('exit',r['exit_code'])

